import{bQ as e,aL as a,u as r,G as d}from"./chunks/framework.C1gZXFVa.js";const o="/assets/090101.D9A-z8Zr.png",m=JSON.parse('{"title":"行情推送流程","description":"挂单、成交、撤单等事件如何变成深度、最新成交与 K 线，并推到客户端；不含行情服务启动装载。","frontmatter":{"title":"行情推送流程","description":"挂单、成交、撤单等事件如何变成深度、最新成交与 K 线，并推到客户端；不含行情服务启动装载。","head":[["meta",{"name":"keywords","content":"开源交易所,交易所开源,交易所源码,开源交易所源码,商业源码,交易所商业源码,数字货币交易所,加密货币交易所,虚拟货币交易所,区块链交易所,撮合引擎,开发撮合引擎,开源撮合引擎,订单簿,现货交易,现货交易所,合约交易,永续合约,合约交易所,期权交易,加密期权,开源OTC,OTC交易,场外交易,法币交易,区块链钱包,数字货币钱包,充值提现,多商户交易所,交易所架构,交易所设计,交易系统设计,资金清算,资产账务,风控系统,行情推送,WebSocket行情,TGEX"}],["link",{"rel":"canonical","href":"https://tgex.net/pages/070509"}],["meta",{"property":"og:url","content":"https://tgex.net/pages/070509"}],["meta",{"property":"og:title","content":"行情推送流程 · TGEX"}],["meta",{"property":"og:description","content":"挂单、成交、撤单等事件如何变成深度、最新成交与 K 线，并推到客户端；不含行情服务启动装载。"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:image","content":"https://tgex.net/og.jpg"}],["meta",{"name":"twitter:title","content":"行情推送流程 · TGEX"}],["meta",{"name":"twitter:description","content":"挂单、成交、撤单等事件如何变成深度、最新成交与 K 线，并推到客户端；不含行情服务启动装载。"}],["meta",{"name":"twitter:image","content":"https://tgex.net/og.jpg"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"TechArticle\\",\\"headline\\":\\"行情推送流程\\",\\"description\\":\\"挂单、成交、撤单等事件如何变成深度、最新成交与 K 线，并推到客户端；不含行情服务启动装载。\\",\\"keywords\\":\\"开源交易所,交易所开源,交易所源码,开源交易所源码,商业源码,交易所商业源码,数字货币交易所,加密货币交易所,虚拟货币交易所,区块链交易所,撮合引擎,开发撮合引擎,开源撮合引擎,订单簿,现货交易,现货交易所,合约交易,永续合约,合约交易所,期权交易,加密期权,开源OTC,OTC交易,场外交易,法币交易,区块链钱包,数字货币钱包,充值提现,多商户交易所,交易所架构,交易所设计,交易系统设计,资金清算,资产账务,风控系统,行情推送,WebSocket行情,TGEX\\",\\"url\\":\\"https://tgex.net/pages/070509\\",\\"mainEntityOfPage\\":\\"https://tgex.net/pages/070509\\",\\"inLanguage\\":\\"zh-CN\\",\\"isPartOf\\":{\\"@type\\":\\"WebSite\\",\\"name\\":\\"TGEX\\",\\"url\\":\\"https://tgex.net/\\"},\\"author\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"TGEX\\"},\\"publisher\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"TGEX\\",\\"logo\\":{\\"@type\\":\\"ImageObject\\",\\"url\\":\\"https://tgex.net/logo.svg\\"}},\\"image\\":\\"https://tgex.net/og.jpg\\"}"]]},"headers":[],"relativePath":"pages/070509.md","filePath":"07.现货手册/05.核心流程/09.行情推送流程.md"}'),n={name:"pages/070509.md"};function p(i,t,h,s,l,c){return a(),r("div",null,[...t[0]||(t[0]=[d('<div class="doc-eyebrow">现货手册 · 核心交易流程 / TGEX KNOWLEDGE BASE</div><h1 id="行情推送流程" tabindex="-1">行情推送流程 <a class="header-anchor" href="#行情推送流程" aria-label="Permalink to &quot;行情推送流程&quot;">​</a></h1><div class="doc-lead">交易过程中的挂单、成交、撤单（或约定行情源）进入行情侧后：加工成深度、最新成交或 K 线，写入缓存并按订阅推给客户端。推送只服务展示，不改订单与资金的权威结果。</div><p align="center"><img src="'+o+'" alt="行情推送流程"></p><p>本文假定行情侧已能推（见<a href="/pages/070507">行情初始化链路</a>）。撮合侧如何产出深度 / 成交外发意向，见<a href="/pages/070508">撮合主流程</a>文末旁路。下文按上图节点展开。</p><h2 id="_1-业务事件进入行情侧" tabindex="-1">1. 业务事件进入行情侧 <a class="header-anchor" href="#_1-业务事件进入行情侧" aria-label="Permalink to &quot;1. 业务事件进入行情侧&quot;">​</a></h2><p>常见来源：</p><table tabindex="0"><thead><tr><th>来源</th><th>典型带来什么</th></tr></thead><tbody><tr><td>挂单 / 撤单 / 成交扣档</td><td>深度变化</td></tr><tr><td>已确认成交</td><td>最新成交、最新价、K 线素材</td></tr><tr><td>约定外部行情源</td><td>展示或策略用的 tick（须标明与本地成交的关系）</td></tr></tbody></table><p>外部 tick 可以驱动展示或策略，<strong>不能</strong>被说成「本地用户之间已经发生的成交」。外部接入另见<a href="/pages/1201#external">机器人与量化</a>。</p><h2 id="_2-按类型加工" tabindex="-1">2. 按类型加工 <a class="header-anchor" href="#_2-按类型加工" aria-label="Permalink to &quot;2. 按类型加工&quot;">​</a></h2><table tabindex="0"><thead><tr><th>类型</th><th>做什么</th><th>不要误解成</th></tr></thead><tbody><tr><td>深度</td><td>未成交订单按价位汇总成盘口档位</td><td>用户全部历史委托</td></tr><tr><td>最新成交</td><td>只反映已确认成交事实</td><td>合约标记价 / 指数价</td></tr><tr><td>K 线</td><td>按时间窗口聚合行情事件</td><td>单笔订单状态</td></tr></tbody></table><p>现货没有合约那套标记价与资金费口径。页面「最新价」通常来自最近确认成交或约定行情源，<strong>不能</strong>替代订单与账务核对。</p><p>设计上应能回答：深度是否只来自本地订单簿？最新成交是否只发已确认成交？K 线窗口与时区如何约定？</p><h2 id="_3-写入行情缓存并标记可推" tabindex="-1">3. 写入行情缓存并标记可推 <a class="header-anchor" href="#_3-写入行情缓存并标记可推" aria-label="Permalink to &quot;3. 写入行情缓存并标记可推&quot;">​</a></h2><p>加工结果写入行情侧缓存，并标记本轮哪些内容需要推（深度、ticker、成交、某周期 K 线等）。<br> 缓存服务于展示与订阅分发，不是撮合内存账本。</p><h2 id="_4-按订阅分发-·-客户端展示" tabindex="-1">4. 按订阅分发 · 客户端展示 <a class="header-anchor" href="#_4-按订阅分发-·-客户端展示" aria-label="Permalink to &quot;4. 按订阅分发 · 客户端展示&quot;">​</a></h2><p>按客户端已订阅的内容推送；未连接时任务可能空转。<br> 主题名与接口路径以接口文档为准，本文不虚构地址。</p><h2 id="_5-断线或丢包时-先快照再增量" tabindex="-1">5. 断线或丢包时：先快照再增量 <a class="header-anchor" href="#_5-断线或丢包时-先快照再增量" aria-label="Permalink to &quot;5. 断线或丢包时：先快照再增量&quot;">​</a></h2><p>客户端应先重新获取权威快照，再按协议接增量。只回放增量、不重建快照，容易在丢包后出现「盘口数量对不上」。</p><p>行情短暂不更新，不一定代表不能交易；行情正常也不证明订单和资金健康——排查交易故障时，行情只能排除展示层的一部分问题。</p><h2 id="本文边界" tabindex="-1">本文边界 <a class="header-anchor" href="#本文边界" aria-label="Permalink to &quot;本文边界&quot;">​</a></h2><table tabindex="0"><thead><tr><th>对照</th><th>说明</th></tr></thead><tbody><tr><td><a href="/pages/070507">行情初始化链路</a></td><td>服务起来后如何装交易对、开推送通道</td></tr><tr><td><a href="/pages/070508">撮合主流程</a></td><td>引擎内成交与外发意向；本文接展示侧</td></tr><tr><td><a href="/pages/0704#orderbook">核心设计 · 订单簿</a></td><td>盘口业务对象；本文讲如何推出去</td></tr></tbody></table><p>同组：<a href="/pages/070507">行情初始化链路</a> · <a href="/pages/070508">撮合主流程</a> · <a href="/pages/070503">撤单主流程</a> · <a href="/pages/0701">业务概述</a> · <a href="/pages/0702">系统架构</a></p>',23)])])}const _=e(n,[["render",p]]);export{m as __pageData,_ as default};
